export type RateCircuitBreakerState = "closed" | "open" | "half-open";

export interface RateCircuitBreakerOptions {
  /** Number of failures in the rolling window that opens the circuit. */
  failureThreshold: number;
  /** Length of the rolling failure window in milliseconds. */
  windowMs: number;
  /** Time for which requests are rejected after the circuit opens. */
  cooldownMs: number;
  /** Injectable monotonic or wall clock. Tests should inject a deterministic clock. */
  now?: () => number;
}

export interface RateCircuitBreakerSnapshot {
  state: RateCircuitBreakerState;
  failureCount: number;
  probeInFlight: boolean;
}

/**
 * A small, deterministic circuit breaker for an exceptional call rate.
 *
 * The breaker does not execute requests itself. Call allowRequest() before an
 * operation and report its outcome with recordSuccess() or recordFailure().
 * A half-open transition reserves the one probe slot, so concurrent callers
 * cannot both pass the breaker.
 */
export class RateCircuitBreaker {
  private readonly failureThreshold: number;
  private readonly windowMs: number;
  private readonly cooldownMs: number;
  private readonly clock: () => number;

  private currentState: RateCircuitBreakerState = "closed";
  private failures: number[] = [];
  private openedAt = 0;
  private probeInFlight = false;

  constructor(options: RateCircuitBreakerOptions) {
    if (!Number.isFinite(options.failureThreshold) || options.failureThreshold <= 0) {
      throw new RangeError("failureThreshold must be a positive finite number");
    }
    if (!Number.isFinite(options.windowMs) || options.windowMs <= 0) {
      throw new RangeError("windowMs must be a positive finite number");
    }
    if (!Number.isFinite(options.cooldownMs) || options.cooldownMs < 0) {
      throw new RangeError("cooldownMs must be a non-negative finite number");
    }

    this.failureThreshold = options.failureThreshold;
    this.windowMs = options.windowMs;
    this.cooldownMs = options.cooldownMs;
    this.clock = options.now ?? Date.now;
  }

  get state(): RateCircuitBreakerState {
    this.refreshState();
    return this.currentState;
  }

  get failureCount(): number {
    this.pruneFailures(this.clock());
    return this.failures.length;
  }

  /**
   * Returns true exactly once for the probe admitted from half-open.
   * Requests made while open, or while that probe is in flight, are rejected.
   */
  allowRequest(): boolean {
    this.refreshState();

    if (this.currentState === "open") {
      return false;
    }
    if (this.currentState === "half-open") {
      if (this.probeInFlight) {
        return false;
      }
      this.probeInFlight = true;
      return true;
    }

    return true;
  }

  /** Records a successful operation. */
  recordSuccess(): void {
    this.refreshState();

    if (this.currentState === "half-open") {
      this.currentState = "closed";
      this.probeInFlight = false;
      this.failures = [];
    }
  }

  /** Records a failed operation. */
  recordFailure(): void {
    const now = this.clock();
    this.refreshState(now);

    if (this.currentState === "half-open") {
      this.open(now);
      return;
    }
    if (this.currentState === "open") {
      return;
    }

    this.pruneFailures(now);
    this.failures.push(now);
    if (this.failures.length >= this.failureThreshold) {
      this.open(now);
    }
  }

  snapshot(): RateCircuitBreakerSnapshot {
    this.refreshState();
    return {
      state: this.currentState,
      failureCount: this.failureCount,
      probeInFlight: this.probeInFlight,
    };
  }

  private refreshState(now = this.clock()): void {
    if (
      this.currentState === "open" &&
      now - this.openedAt >= this.cooldownMs
    ) {
      this.currentState = "half-open";
      this.probeInFlight = false;
      this.failures = [];
    }
  }

  private open(now: number): void {
    this.currentState = "open";
    this.openedAt = now;
    this.probeInFlight = false;
    this.failures = [];
  }

  private pruneFailures(now: number): void {
    const windowStart = now - this.windowMs;
    this.failures = this.failures.filter((failureAt) => failureAt > windowStart);
  }
}

export function createRateCircuitBreaker(
  options: RateCircuitBreakerOptions,
): RateCircuitBreaker {
  return new RateCircuitBreaker(options);
}

